import { Leaf, Users, ShoppingBag, Truck, ChevronDown, Loader2, AlertCircle } from 'lucide-react';
import { ProduceCard } from '../features/produce/ProduceCard';
import { useProduceData } from '../features/produce/useProduceData';
import { useSearch } from '../context/SearchContext'; // Import Search Context

export const Marketplace = () => {
  // 1. ALL Hooks must be inside the component body
  const { produce, isLoading, error } = useProduceData();
  const { searchQuery } = useSearch();

  // 2. Dynamic Search Filtering (Only runs when produce or searchQuery changes)
  const filteredProduce = produce.filter(item => 
    item.cropType.toLowerCase().includes((searchQuery || '').toLowerCase()) ||
    item.location.toLowerCase().includes((searchQuery || '').toLowerCase())
  );

  // 3. Dynamic Statistics Calculations (Based on the live database!)
  const totalProduceKg = produce.reduce((sum, item) => sum + item.weightKg, 0);
  const activeFarmersCount = new Set(produce.map(item => item.farmerName)).size;

  const statCards = [
    { label: 'Total Produce Available', value: `${totalProduceKg.toLocaleString()} kg`, icon: Leaf, color: 'text-farmGreen', bg: 'bg-farmGreen-light' },
    { label: 'Active Farmers', value: activeFarmersCount.toString(), icon: Users, color: 'text-blue-600', bg: 'bg-blue-100' },
    { label: 'Registered Buyers', value: 'Live', icon: ShoppingBag, color: 'text-red-600', bg: 'bg-red-100' },
    { label: 'Ongoing Deliveries', value: 'Live', icon: Truck, color: 'text-teal-600', bg: 'bg-teal-100' },
  ];

  return (
    <div className="space-y-6">
      
      {/* Statistics Row */}
      <section className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
        {statCards.map((stat, idx) => (
          <div key={idx} className="flex items-center p-4 bg-white rounded-xl border border-gray-200 shadow-sm">
            <div className={`p-3 rounded-xl ${stat.bg} ${stat.color} mr-4`}>
              <stat.icon size={24} />
            </div>
            <div>
              <h4 className="text-2xl font-extrabold text-gray-900">{stat.value}</h4>
              <p className="text-sm font-medium text-gray-500">{stat.label}</p>
            </div>
          </div>
        ))}
      </section>

      {/* Promotional Banner */}
      <section className="relative overflow-hidden rounded-2xl bg-farmGreen shadow-sm">
        <div className="relative z-10 p-8 md:p-12 max-w-2xl text-white">
          <h2 className="text-3xl md:text-4xl font-extrabold mb-3">
            Fresh Produce<br />Stronger Communities
          </h2>
          <p className="text-lg text-green-50 mb-6 font-medium max-w-md">
            Connecting farmers to buyers — even in remote areas.
          </p>
          <button className="px-6 py-2.5 bg-white text-farmGreen rounded-lg font-bold hover:bg-gray-50 transition-colors flex items-center gap-2">
            Browse Produce <span aria-hidden="true">&rarr;</span>
          </button>
        </div>
      </section>

      {/* Filter & Sort Bar */}
      <section className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm flex flex-col lg:flex-row lg:items-center justify-between gap-4">
        <div className="flex gap-2 overflow-x-auto pb-2 lg:pb-0 hide-scrollbar">
          {['All Produce', 'Fruits', 'Vegetables', 'Grains', 'Tubers', 'Others'].map((cat, idx) => (
            <button 
              key={cat} 
              className={`whitespace-nowrap px-4 py-2 rounded-full text-sm font-semibold transition-colors ${
                idx === 0 ? 'bg-farmGreen text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>
        <div className="flex flex-wrap items-center gap-3">
          {['Select Location', 'Crop Type', 'Quantity', 'Price Range', 'Sort By'].map((filter) => (
            <div key={filter} className="flex items-center gap-2 px-3 py-2 border border-gray-200 rounded-lg text-sm text-gray-600 cursor-pointer hover:bg-gray-50">
              <span className="font-medium">{filter}</span>
              <ChevronDown size={14} />
            </div>
          ))}
        </div>
      </section>

      {/* Dynamic Produce Grid */}
      <section className="pb-8">
        {error && (
          <div className="p-4 bg-red-50 text-red-700 rounded-xl flex items-center gap-3 border border-red-200">
            <AlertCircle size={20} />
            <span className="font-medium">{error}</span>
          </div>
        )}

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20 text-gray-400">
            <Loader2 className="animate-spin mb-4 text-farmGreen" size={40} />
            <p className="font-medium">Loading marketplace inventory...</p>
          </div>
        ) : !error && filteredProduce.length === 0 ? (
          <div className="text-center py-20 bg-white rounded-xl border border-gray-200 shadow-sm">
            <Leaf className="mx-auto text-gray-300 mb-3" size={48} />
            <h3 className="text-lg font-bold text-gray-900">No Produce Found</h3>
            <p className="text-gray-500">Try adjusting your search query.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {/* Notice we use filteredProduce here, not produce! */}
            {filteredProduce.map((item) => (
              <ProduceCard key={item._id} item={item} />
            ))}
          </div>
        )}
      </section>

    </div>
  );
};
